try {
    response = await aiApi.generateTripStream({
        prompt: promptToSend,
        user_id: activeUserId,
        onProgress: (p) => {
            setAiProgress(`${p.message} (${p.percent}%)`)
        }
    })
} catch (streamErr) {
    console.warn("⚠️ [TripDialogs] Stream failed, falling back to sync:", streamErr)
    response = await aiApi.generateTrip({
        prompt: promptToSend,
        user_id: activeUserId
    })
}

